// Bundle dispatch workflow (library: no main procedure).
//
// fulfill tries BOTH lines from `preferred`, then BOTH from `fallback`, and
// otherwise emits a single `deferred` event and returns normally.
//
// Shortage is decided before reserving, with an exact availability test that
// accounts for both lines drawing on the same SKU. A shortage therefore never
// creates a hold, so only an attempt that has reserved both lines pauses, and
// nothing needs to be caught: any non-shortage domain failure (unknown
// warehouse, bad quantity or name, duplicate hold, ...) propagates with its
// original code, location and stack instead of being swallowed or masked.
// Inputs that are not well formed skip the test and go straight to the
// preferred attempt so the atomic operation reports the precise error.
//
// Each attempt runs inside its own transaction: if anything fails after the
// first reservation, both holds are rolled back before the error propagates.
// Only parameters and locals of these procedures are touched, so same-named
// caller variables are never read or written, and the procedure composes with
// a caller's enclosing transaction (an outer rollback undoes the attempt).

proc fulfill(order: string, sku_a: string, qty_a: int,
             sku_b: string, qty_b: int, preferred: string, fallback: string) {
    let malformed: bool = qty_a <= 0 || qty_b <= 0
                          || len(sku_a) == 0 || len(sku_b) == 0;
    if (malformed
        || (sku_a == sku_b && available(preferred, sku_a) >= qty_a + qty_b)
        || (sku_a != sku_b && available(preferred, sku_a) >= qty_a
                           && available(preferred, sku_b) >= qty_b)) {
        fulfill_attempt(order, sku_a, qty_a, sku_b, qty_b, preferred);
        return;
    }
    if ((sku_a == sku_b && available(fallback, sku_a) >= qty_a + qty_b)
        || (sku_a != sku_b && available(fallback, sku_a) >= qty_a
                           && available(fallback, sku_b) >= qty_b)) {
        fulfill_attempt(order, sku_a, qty_a, sku_b, qty_b, fallback);
        return;
    }
    emit "deferred" { order: order; reason: "SHORTAGE"; };
}

// One fully atomic attempt from a single warehouse: reserve both lines, pause
// for dispatch approval, then ship both lines completely.
proc fulfill_attempt(order: string, sku_a: string, qty_a: int,
                     sku_b: string, qty_b: int, warehouse: string) {
    transaction {
        reserve(order + ".a", warehouse, sku_a, qty_a);
        reserve(order + ".b", warehouse, sku_b, qty_b);
        pause order + ":reserved";
        ship(order + ".a", qty_a);
        ship(order + ".b", qty_b);
        emit "fulfilled" {
            order: order;
            warehouse: warehouse;
            units: qty_a + qty_b;
        };
    }
}
EOF
