     __slots__ = ("op", "pos", "step", "a", "b", "c", "shape")

     def __init__(self, op, pos, step, a=None, b=None, c=None):
         self.op = op
         self.pos = pos
         self.step = step
         self.a = a
         self.b = b
         self.c = c
         self.shape = None

     def __repr__(self):
         return "%s(%r,%r,%r)" % (OPNAMES[self.op], self.a, self.b, self.c)


