import json
import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from harness import run, chain  # noqa: E402

INV = {"warehouses": {"east": {"gear": 10, "zero": 0}, "west": {}}}


def ev(result):
    return [(e["name"], e["data"]) for e in result["events"]]


class Base(unittest.TestCase):
    def ok(self, src, inv=INV, lib=None):
        code, out, diag = run(src, inv, lib)
        self.assertEqual(code, 0, diag)
        # every program is also checked through a pause/resume chain
        c2, out2, diag2, labels = chain(src, inv, lib)
        self.assertEqual(c2, 0, diag2)
        self.assertEqual(out, out2)
        return out

    def fails(self, src, category, inv=INV, lib=None):
        code, out, diag = run(src, inv, lib)
        self.assertEqual(diag and diag["error"], category, (code, diag))
        self.assertIsNone(out)
        if category in ("DOMAIN", "RUNTIME"):
            c2, out2, diag2, _ = chain(src, inv, lib)
            diag.pop("file", None); diag2.pop("file", None)
            self.assertEqual(diag2, diag)
        return diag


class Semantics(Base):
    def test_arith(self):
        out = self.ok('''proc main() { emit "a" { d: -7 / 2; m: -7 % 2; n: 7 % -2;
          p: 1 + 2 * 3 - 4; s: "a" + "b"; c: 1 < 2 == true; b: !(1 == 2) && true || false;
          big: 99999999999999999999 * 99999999999999999999; l: len("h\\u00e9"); }; }''')
        self.assertEqual(ev(out)[0][1], {"d": -3, "m": -1, "n": 1, "p": 3, "s": "ab",
                                         "c": True, "b": True,
                                         "big": 99999999999999999999 ** 2, "l": 2})

    def test_steps_loop(self):
        out = self.ok('''proc main() { let i: int = 0; while (i < 3) { set i = i + 1;
            if (i == 2) { continue; } pause "p"; } }''')
        # let, while, 3x(set, if) + continue once + 2 pauses
        self.assertEqual(out["stats"], {"steps": 1 + 1 + 6 + 1 + 2, "committed": 0,
                                        "rolled_back": 0})

    def test_break_commits(self):
        out = self.ok('''proc main() { let i: int = 0; while (true) {
            transaction { transaction { set i = i + 1; pause "x";
              if (i == 3) { break; } } } }
            emit "i" { i: i; }; }''')
        self.assertEqual(ev(out), [("i", {"i": 3})])
        self.assertEqual(out["stats"]["committed"], 6)

    def test_return_commits_only_exited(self):
        out = self.ok('''
        proc f() { transaction { transaction { emit "in" {}; pause "f"; return; } } emit "never" {}; }
        proc main() { transaction { f(); pause "m"; assert false; } recover (e) { emit code(e) {}; }
          emit "after" {}; }''')
        self.assertEqual(ev(out), [("ASSERT", {}), ("after", {})])
        self.assertEqual(out["stats"]["committed"], 2)
        self.assertEqual(out["stats"]["rolled_back"], 1)

    def test_nested_rollback_and_recover_error(self):
        out = self.ok('''proc main() { let x: int = 1;
          transaction {
            transaction { set x = 2; receive("east", "new", 4); emit "inner" {}; }
            transaction { set x = 3; assert false; } recover (e) { emit "rec" { c: code(e); x: x; };
              pause "in-recover"; reserve("h", "east", "gear", 100); }
          } recover (outer) { emit "outer" { c: code(outer); x: x; }; }
          emit "end" { x: x; }; }''')
        self.assertEqual(ev(out), [("outer", {"c": "SHORTAGE", "x": 1}), ("end", {"x": 1})])
        self.assertNotIn("new", out["warehouses"]["east"])
        self.assertEqual(out["stats"], {"steps": 14, "committed": 1, "rolled_back": 2})

    def test_caller_bindings_restored(self):
        out = self.ok('''
        proc f(x: int) { let y: int = x; set x = 100; pause "f"; assert false; }
        proc main() { let x: int = 1; let y: string = "s";
          transaction { set x = 5; set y = "t"; f(x); } recover (e) { emit "r" { x: x; y: y; }; } }''')
        self.assertEqual(ev(out), [("r", {"x": 1, "y": "s"})])

    def test_shadowing_and_initializer(self):
        out = self.ok('''proc main() { let x: int = 1;
          if (true) { let x: int = x + 10; set x = x + 1; pause "a"; emit "inner" { x: x; }; }
          emit "outer" { x: x; };
          transaction { assert false; } recover (e) {
             if (true) { let e: string = "shadow"; pause "b"; emit e { c: 1; }; }
             emit code(e) {}; } }''')
        self.assertEqual(ev(out), [("inner", {"x": 12}), ("outer", {"x": 1}),
                                   ("shadow", {"c": 1}), ("ASSERT", {})])

    def test_named_and_default_args(self):
        out = self.ok('''proc g(a: int, b: string = "d", c: bool = false, n: int = -3) {
            emit b { a: a; c: c; n: n; }; }
          proc main() { g(1); g(2, c = true); g(n = 5, a = 3); }''')
        self.assertEqual(ev(out), [("d", {"a": 1, "c": False, "n": -3}),
                                   ("d", {"a": 2, "c": True, "n": -3}),
                                   ("d", {"a": 3, "c": False, "n": 5})])

    def test_operations(self):
        out = self.ok('''proc main() {
          move("east", "west", "gear", 4); reserve("h", "west", "gear", 3);
          release("h", 1); ship("h", 2); emit "s" { a: available("west", "gear");
          o: onhand("west", "gear"); r: remaining("h"); m: onhand("west", "none"); };
          transaction { move("west", "east", "gear", 3); } recover (e) { emit code(e) {}; }
          transaction { move("east", "east", "gear", 1); } recover (e) { emit code(e) {}; }
          transaction { reserve("h", "east", "gear", 1); } recover (e) { emit code(e) {}; }
          transaction { receive("east", "gear", 0); } recover (e) { emit code(e) {}; }
          transaction { receive("east", "", 1); } recover (e) { emit code(e) {}; }
          transaction { receive("nowhere", "gear", 1); } recover (e) { emit code(e) {}; }
          transaction { ship("nope", 1); } recover (e) { emit code(e) {}; }
          transaction { release("h", 1); } recover (e) { emit code(e) {}; }
          transaction { let r: int = remaining("zz"); } recover (e) { emit code(e) {}; }
        }''')
        self.assertEqual(ev(out), [("s", {"a": 2, "o": 2, "r": 0, "m": 0}),
            ("SHORTAGE", {}), ("SAME_WAREHOUSE", {}), ("DUPLICATE_HOLD", {}),
            ("QUANTITY", {}), ("NAME", {}), ("WAREHOUSE", {}), ("HOLD", {}),
            ("SHORTAGE", {}), ("HOLD", {})])
        self.assertEqual(out["warehouses"], {"east": {"gear": 6, "zero": 0},
                                             "west": {"gear": 2}})
        self.assertEqual(out["holds"], {"h": {"warehouse": "west", "sku": "gear",
                                              "remaining": 0}})

    def test_short_circuit(self):
        out = self.ok('''proc main() { emit "x" { a: false && remaining("x") > 0;
            b: true || 1 / 0 == 1; }; }''')
        self.assertEqual(ev(out), [("x", {"a": False, "b": True})])

    def test_step_limit(self):
        self.ok('''proc main() { let i: int = 0; while (i < 19998) { set i = i + 1; } }''')
        d = self.fails('''proc main() { let i: int = 0; while (i < 19999) { set i = i + 1; } }''',
                       "RUNTIME")
        self.assertEqual(d["stack"], ["main"])

    def test_runtime_and_domain_diagnostics(self):
        d = self.fails('proc f() {\n  let x: int = 1 / 0;\n}\nproc main() { f(); }', "RUNTIME")
        self.assertEqual((d["line"], d["column"], d["stack"]), (2, 18, ["main", "f"]))
        d = self.fails('proc f() {\n  transaction { pause "z";\n assert false; }\n}\n'
                       'proc main() { transaction { f(); } }', "DOMAIN")
        self.assertEqual((d["code"], d["line"], d["column"], d["stack"]),
                         ("ASSERT", 3, 2, ["main", "f"]))
        d = self.fails('proc main() { transaction { 1/0; } recover (e) {} }', "SYNTAX")
        d = self.fails('proc main() { transaction { let x: int = 1 / 0; } recover (e) {} }',
                       "RUNTIME")


class Static(Base):
    CASES = [
        'proc main() { let x: int = y; }',
        'proc main() { let x: int = true; }',
        'proc main() { let x: int = 1; let x: int = 2; }',
        'proc f(x: int) { let x: int = 1; } proc main() {}',
        'proc main() { let x: int = x; }',
        'proc main() { set x = 1; }',
        'proc main() { break; }',
        'proc f() { break; } proc main() { while (true) { f(); } }',
        'proc main() { f(); }',
        'proc main() { len("a"); }',
        'proc len() {} proc main() {}',
        'proc main() { let x: int = g(); } proc g() {}',
        'proc main() { f(); } proc f() { g(); } proc g() { f(); }',
        'proc f() { f(); } proc main() {}',
        'proc main(x: int = 1) {}',
        'proc f() {}',
        'proc main() {} proc main() {}',
        'proc f(a: int = 1, b: int) {} proc main() {}',
        'proc f(a: int = true) {} proc main() {}',
        'proc f(a: int, a: int) {} proc main() {}',
        'proc f(a: int) {} proc main() { f(1, 2); }',
        'proc f(a: int) {} proc main() { f(); }',
        'proc f(a: int) {} proc main() { f(b = 1); }',
        'proc f(a: int) {} proc main() { f(1, a = 1); }',
        'proc f(a: int, b: int) {} proc main() { f(a = 1, 2); }',
        'proc f(a: int) {} proc main() { f("x"); }',
        'proc main() { emit "a" { x: 1; x: 2; }; }',
        'proc main() { emit 1 {}; }',
        'proc main() { if (1) {} }',
        'proc main() { assert 1; }',
        'proc main() { pause 1; }',
        'proc main() { let b: bool = 1 < 2 < 3; }',
        'proc main() { let b: bool = 1 == "1"; }',
        'proc main() { let b: bool = true < false; }',
        'proc main() { let x: int = "a" - "b"; }',
        'proc main() { let x: int = -true; }',
        'proc main() { transaction {} recover (e) { set e = e; } }',
        'proc main() { transaction {} recover (e) { let e: int = 1; } }',
        'proc main() { transaction {} recover (e) { emit "x" { e: e; }; } }',
        'proc f(e: string) {} proc main() { transaction {} recover (e) { f(e); } }',
        'proc main() { transaction {} recover (e) { let b: bool = e == e; } }',
        'proc main() { let s: string = "x"; let c: string = code(s); }',
        'proc main() { let c: int = len(x = "a"); }',
        'proc main() { let c: int = onhand("a"); }',
        'proc main() { receive("a", "b", "c"); }',
        'proc main() { transaction {} recover (e) {} let c: string = code(e); }',
        'proc main() { while (true) { } continue; }',
        'proc main() {} proc u() { if (true) { let q: int = "bad"; } }',
    ]

    def test_static(self):
        for src in self.CASES:
            with self.subTest(src=src):
                d = self.fails(src, "STATIC")
                self.assertIn("line", d)
                self.assertIn("file", d)

    def test_library_main_and_static_in_library(self):
        code, out, diag = run('proc main() { f(); }', INV, 'proc f() { let x: int = "s"; }')
        self.assertEqual((code, diag["error"]), (3, "STATIC"))
        self.assertTrue(diag["file"].endswith("l.stock"))

    def test_valid_edge_programs(self):
        self.ok('proc main() { let len: int = len("ab"); let code: int = len; }')
        self.ok('proc f(x: int) {} proc main() { f(x = 1); }')
        self.ok('proc main() { transaction {} recover (e) { if (true) { let e: int = 1; set e = 2; } } }')
        self.ok('proc main() { g(); } proc g() { h(); h(); } proc h() {}')


class Syntax(Base):
    CASES = [
        'proc main() { let x: int = 1 }',
        'proc main() { let let: int = 1; }',
        'proc main() { let x: int = 1 & 2; }',
        'proc main() { let s: string = "abc; }',
        'proc main() { let s: string = "\\x"; }',
        'proc main() { @ }',
        'proc main() {',
        'proc main() { return }',
        'proc f(a: int = 1 + 1) {} proc main() {}',
        'proc main() { x; }',
        'proc main() { emit "a" { x: 1;; }; }',
        'proc main() { let x: float = 1; }',
        'proc main() { if true {} }',
        'main() {}',
    ]

    def test_syntax(self):
        for src in self.CASES:
            with self.subTest(src=src):
                d = self.fails(src, "SYNTAX")
                self.assertIn("column", d)

    def test_comments_and_trailing(self):
        self.ok('// hi\nproc main() { emit "a" { x: 1; }; // c\n emit "b" { x: 1 }; }')


class Inputs(Base):
    def test_bad_inputs(self):
        for inv in ['{"warehouses":{"e":{"g":true}}}', '{"warehouses":{"e":{"g":-1}}}',
                    '{"warehouses":{"e":{"g":1.0}}}', '{"warehouses":{}, "x": 1}',
                    '{"warehouses":{"e":{"g":1,"g":2}}}', '{"warehouses":[]}', 'nope',
                    '{"warehouses":{"e":{"g":NaN}}}', '{"warehouses":{"":{}}}',
                    '{"warehouses":{"e":{"":1}}}', '[]', '{"warehouses":{"e":[]}}']:
            with self.subTest(inv=inv):
                self.fails('proc main() {}', "INPUT", inv=inv)

    def test_empty_and_zero(self):
        out = self.ok('proc main() { let a: int = onhand("w", "x"); }',
                      inv='{"warehouses":{"w":{},"e":{"z":0}}}')
        self.assertEqual(out["warehouses"], {"w": {}, "e": {"z": 0}})


if __name__ == "__main__":
    unittest.main()

