"""Differential fuzz: uninterrupted execution vs suspend/JSON/reload at every pause."""
import json
import random
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from stockroom import checkpoint  # noqa: E402
from stockroom.compiler import compile_unit  # noqa: E402
from stockroom.errors import StockError  # noqa: E402
from stockroom.parser import parse  # noqa: E402
from stockroom.vm import VM, Suspend, load_state  # noqa: E402

INV = {"warehouses": {"e": {"g": 6, "s": 3}, "w": {"g": 2}}}


class Gen:
    def __init__(self, rng):
        self.r = rng
        self.n = 0

    def fresh(self):
        self.n += 1
        return "v%d" % self.n

    def iexpr(self, env, d=0):
        r = self.r
        ints = [n for n, t in env if t == "int"]
        c = r.randrange(6 if d < 2 else 2)
        if c == 0 or (c == 1 and not ints):
            return str(r.randrange(-3, 6))
        if c == 1:
            return r.choice(ints)
        if c == 2:
            return "(%s %s %s)" % (self.iexpr(env, d + 1), r.choice("+-*"), self.iexpr(env, d + 1))
        if c == 3:
            return 'available("%s", "g")' % r.choice("ew")
        if c == 4:
            return 'onhand("e", "%s")' % r.choice("gsq")
        return "(%s / %s)" % (self.iexpr(env, d + 1), r.choice(["2", "-3", "7"]))

    def bexpr(self, env):
        r = self.r
        bools = [n for n, t in env if t == "bool"]
        if bools and r.random() < 0.3:
            return r.choice(bools)
        return "%s %s %s" % (self.iexpr(env), r.choice(["<", "<=", "==", "!=", ">"]), self.iexpr(env))

    def block(self, env, depth, in_loop, procs, errs):
        env = list(env)
        out = []
        for _ in range(self.r.randrange(1, 5)):
            out.append(self.stmt(env, depth, in_loop, procs, errs))
        return "{ " + " ".join(out) + " }"

    def stmt(self, env, depth, in_loop, procs, errs):
        r = self.r
        ints = [n for n, t in env if t == "int"]
        c = r.randrange(16)
        if c == 0:
            name = self.fresh()
            st = "let %s: int = %s;" % (name, self.iexpr(env))
            env.append((name, "int"))
            return st
        if c == 1 and ints:
            return "set %s = %s;" % (r.choice(ints), self.iexpr(env))
        if c == 2:
            return 'pause "%s";' % r.choice(["a", "b", "a"])
        if c == 3:
            fields = "; ".join("%s: %s" % (k, self.iexpr(env)) for k in ("x", "y")[:r.randrange(3)])
            if errs and r.random() < 0.5:
                return 'emit code(%s) { %s };' % (r.choice(errs), fields)
            return 'emit "%s" { %s };' % (r.choice("pqr"), fields)
        if c == 4 and depth < 4:
            st = "if (%s) %s" % (self.bexpr(env), self.block(env, depth + 1, in_loop, procs, errs))
            if r.random() < 0.5:
                st += " else " + self.block(env, depth + 1, in_loop, procs, errs)
            return st
        if c == 5 and depth < 4:
            k = self.fresh()
            body = self.block(env + [(k, "int")], depth + 1, True, procs, errs)
            st = "let %s: int = 0; while (%s < %d) { set %s = %s + 1; %s }" % (
                k, k, r.randrange(1, 4), k, k, body[1:-1])
            env.append((k, "int"))
            return st
        if c in (6, 7) and depth < 4:
            st = "transaction " + self.block(env, depth + 1, in_loop, procs, errs)
            if r.random() < 0.7:
                e = r.choice(["e", "f", "e"])
                st += " recover (%s) %s" % (e, self.block(
                    [x for x in env if x[0] != e] + [(e, "error")], depth + 1, in_loop, procs,
                    [x for x in errs if x != e] + [e]))
            return st
        if c == 8:
            return "assert %s;" % self.bexpr(env)
        if c == 9:
            return 'reserve("h%d", "%s", "%s", %s);' % (r.randrange(4), r.choice("ew"), r.choice("gs"), self.iexpr(env))
        if c == 10:
            return 'ship("h%d", %s);' % (r.randrange(4), r.randrange(1, 3))
        if c == 11:
            return 'move("%s", "%s", "g", %d);' % (r.choice("ew"), r.choice("ew"), r.randrange(1, 4))
        if c == 12:
            return 'receive("%s", "%s", %d);' % (r.choice("ew"), r.choice("gq"), r.randrange(0, 3))
        if c == 13 and procs:
            p = r.choice(procs)
            return "%s(%s);" % (p, self.iexpr(env))
        if c == 14 and in_loop:
            return r.choice(["break;", "continue;"])
        if c == 15 and r.random() < 0.3:
            return "return;"
        return 'emit "n" {};'

    def program(self):
        procs = []
        text = []
        for i in range(self.r.randrange(0, 4)):
            name = "p%d" % i
            body = self.block([("a", "int")], 0, False, list(procs), [])
            text.append("proc %s(a: int) %s" % (name, body))
            procs.append(name)
        text.append("proc main() %s" % self.block([], 0, False, procs, []))
        return "\n".join(text)


def outcome(fn):
    try:
        return ("ok", fn())
    except StockError as exc:
        return (exc.category, exc.code, exc.pos, exc.stack)


def straight(src):
    unit = compile_unit([], parse(src, "program"))
    vm = VM(unit, json.loads(json.dumps(INV["warehouses"])))
    vm.run()
    return vm.result()


def resumed(src):
    unit = compile_unit([], parse(src, "program"))
    vm = VM(unit, json.loads(json.dumps(INV["warehouses"])), durable=True)
    ident = {"program": "0" * 64, "inventory": "0" * 64, "library": None}
    pauses = 0
    while True:
        try:
            vm.run()
            return vm.result()
        except Suspend:
            pauses += 1
            data = checkpoint.build(ident, vm.label, vm.pause_count, vm.dump_state())
            env = checkpoint.parse(data)
            unit = compile_unit([], parse(src, "program"))  # fresh compilation
            vm = load_state(unit, env["state"], env["label"], env["pause_count"])


def main(count=400, seed=1):
    rng = random.Random(seed)
    stats = {}
    for i in range(count):
        src = Gen(rng).program()
        a = outcome(lambda: straight(src))
        b = outcome(lambda: resumed(src))
        stats[a[0]] = stats.get(a[0], 0) + 1
        if a != b:
            print("MISMATCH", i)
            print(src)
            print(a)
            print(b)
            return 1
    print("ok", stats)
    return 0


if __name__ == "__main__":
    sys.exit(main(*map(int, sys.argv[1:])))

